        self, user_input: dict[str, Any] | None = None
    ) -> ConfigFlowResult:
        """Handle the user step to pick a discovered device."""

        if user_input is not None:
            address = user_input[CONF_MAC]
            self._discovery_info = self._discovered_devices[address]

            unique_id = dr.format_mac(address)
            await self.async_set_unique_id(unique_id)
            self._abort_if_unique_id_configured()

            return await self.async_step_confirm()

        for discovery_info in bluetooth.async_discovered_service_info(self.hass):
            if device_filter(discovery_info.advertisement):
                self._discovered_devices[discovery_info.address] = discovery_info

        if not self._discovered_devices:
            return self.async_abort(reason="no_devices_found")

        return self.async_show_form(
            step_id="user",
            data_schema=vol.Schema(
                {
                    vol.Required(CONF_MAC): vol.In(
